`decimal_date` incorrectly returns `NaN` when the input is New Year.  For example,

```
x <- ymd("2013-01-01")
decimal_date(x)  #returns NaN, not 2013
```

Here's my suggested fix.

```
decimal_date.default <- function (date) 
{
    if (any(!inherits(date, c("POSIXt", "POSIXct", "POSIXlt", "Date")))) 
        stop("date(s) not in POSIXt or Date format")
    secs_since_start_of_year <- function(x)
    {
      as.numeric(difftime(
        x, 
        floor_date(date, "year"), 
        units = "secs"
      ))
    }
    numerator <- secs_since_start_of_year(date)
    decimal <- ifelse(
      numerator > 0, 
      {
        denominator <- secs_since_start_of_year(ceiling_date(date, "year"))
        numerator / denominator
      }, 0
    )

    year(date) + decimal
}

test_that(
  "decimal_date.default works with New Year",
  {
    x <- seq(ymd("0001-01-01"), ymd("9999-01-01"), by = "1 year")
    expected <- 1:9999
    expect_that(ddd(x), equals(expected)) 
  }
)

test_that(
  "decimal_date.default works with 2nd Jan",
  {
    #ceiling_date seems to fail with 9999, so stop one year earlier
    x <- seq(ymd("0001-01-02"), ymd("9998-01-02"), by = "1 year")
    expected <- 1:9998 + 1 / ifelse(leap_year(x), 366, 365)
    expect_that(ddd(x), equals(expected)) 
  }
)
```

Once you have run roxygenise, you can use the following code to run all of the examples in the documentation.  You might find the following function helpful - it's a bit faster than using R CMD check because it just runs the examples:

```
library(plyr)
library(tools)

run_examples <- function(path) {
  files <- dir(path, full = TRUE)

  parsed <- llply(files, parse_Rd)
  names(parsed) <- basename(files)

  extract_examples <- function(rd) {
    tags <- tools:::RdTags(rd)
    paste(unlist(rd[tags == "\\examples"]), collapse = "")
  }

  examples <- llply(parsed, extract_examples)
  m_ply(cbind(file = names(examples), example = examples), 
    function(file, example) {
      cat("Checking ", file, "...\n", sep = "")
      eval(parse(text = example))
    }
  )  
}
```

